Exactoo, esa es la técnica clásica. También podrías guardar el índice donde lo encontraste y usar -1 como señal de "no encontrado". Las dos funcionan. Mira el programa completo usando el índice:

```c
#include <stdio.h>

#define N 4

struct Producto {
    int codigo;
    char nombre[50];
    float precio;
};

int main() {
    struct Producto catalogo[N] = {
        {101, "Lapicero",   1.50},
        {102, "Cuaderno",   3.75},
        {103, "Borrador",   0.80},
        {104, "Regla",      2.00}
    };

    int buscar;
    printf("Ingrese el código del producto: ");
    scanf("%d", &buscar);

    int indice = -1;
    for (int i = 0; i < N; i++) {
        if (catalogo[i].codigo == buscar) {
            indice = i;
            break;
        }
    }

    if (indice != -1) {
        printf("Producto encontrado:\n");
        printf("  Nombre: %s\n", catalogo[indice].nombre);
        printf("  Precio: %.2f\n", catalogo[indice].precio);
    } else {
        printf("Producto con código %d no encontrado.\n", buscar);
    }

    return 0;
}
```

¿Ves por qué usamos `indice = -1` como valor inicial?
